const order = $input.first().json;
const data = order.body || order;
return [{ json: { orderId: data.id || data.order_id || 'N/A', customerName: data.customer?.name || data.billing?.first_name || 'Customer', customerEmail: data.customer?.email || data.billing?.email || '', total: data.total || data.total_price || '0', currency: data.currency || 'USD', items: Array.isArray(data.line_items) ? data.line_items.map(i => i.name || i.title).join(', ') : 'Items', date: new Date().toISOString() } }];

